event.script:
/*
validation.isValidLength(strSumAndReportBodyPage.subStrSummary.subLineRec.txtStrNo,10,"STRNo")&&
validation.isValidLength(strSumAndReportBodyPage.subStrSummary.subLineRec.txtSubmissionNo,20,"SubmissionNo")&&
validation.isValidDate(strSumAndReportBodyPage.subStrSummary.subLineRec.dtSubmission,"Submission")&&
validation.isValidDate(strSumAndReportBodyPage.subStrSummary.subLineRec.dtAcknowledgementIssue,"Acknowdledge")&&
validation.isValidDate(strSumAndReportBodyPage.subStrSummary.subLineRec.dtConsentLetterIssue,"Consent")&&
validation.isValidSubmitNo(strSumAndReportBodyPage.subStrSummary.subLineRec.txtSubmissionNo)&&
*/

var errorMessage=[];
var result="";

if(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCapNSL.rawValue == "true" &&
validation2.isSectionEmpty("STR.subjectPage.subSubjectEntity[*]") &&
validation2.isSectionEmpty("STR.subjectPage.subSubjectEntity[*]") &&
validation2.isSectionEmpty("STR.organPage.subOrganEntity[*]") &&
validation2.isSectionEmpty("STR.phonePage.tabPhone.Row1[*]") &&
validation2.isSectionEmpty("STR.addressPage.tabAddress.Row1[*]")
){
if (strSumAndReportBodyPage.subStrSummary.subAttachment.NoOfAttachments.rawValue < 1){
errorMessage.push("Please upload at least one attachment.");
}
}else{
if (!validation.isChkedRelatedToExistingInvestigation()){

formatter.setErrorBorder(strSumAndReportBodyPage.subStrSummary.subSpecialCases.rdExistInvestigat);

errorMessage.push( "Please check for \"Report related to existing investigation.\"") ;

} else{
formatter.clearErrorBorder(strSumAndReportBodyPage.subStrSummary.subSpecialCases.rdExistInvestigat);
}


if (!validation.isConditionalMandatory(strSumAndReportBodyPage.subStrSummary.subSpecialCases.rdExistInvestigat,1,strSumAndReportBodyPage.subStrSummary.subSpecialCases.txtInvestigatUnit)){

errorMessage.push("Investigation unit must be filled.");
}

if (!validation.isConditionalMandatory(strSumAndReportBodyPage.subStrSummary.subSpecialCases.rdExistInvestigat,1,strSumAndReportBodyPage.subStrSummary.subSpecialCases.txtRef)){

errorMessage.push("Reference must be filled.");

}

if (!validation.isValidLength(strSumAndReportBodyPage.subReportingBody.txtOrganID,8)){

formatter.setErrorBorder(strSumAndReportBodyPage.subReportingBody.txtOrganID);
errorMessage.push("Organization ID must be in length 8.");

} else{
formatter.clearErrorBorder(strSumAndReportBodyPage.subReportingBody.txtOrganID);
}


if (!validation.isValidLength(strSumAndReportBodyPage.subReportingBody.txtReportOfficerID,2)){

formatter.setErrorBorder(strSumAndReportBodyPage.subReportingBody.txtReportOfficerID);

errorMessage.push("Reporting Officer ID must be in length 2.");
} else{
formatter.clearErrorBorder(strSumAndReportBodyPage.subReportingBody.txtReportOfficerID);
}


if (!validation.isChkedDisclosureReason()){
formatter.setErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCap405);
formatter.setErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCap455);
formatter.setErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCap575);
formatter.setErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCapNSL);

errorMessage.push("Please check at least one Reason for Disclosure.");

} else{
formatter.clearErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCap405);
formatter.clearErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCap455);
formatter.clearErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCap575);
formatter.clearErrorBorder(strSumAndReportBodyPage.subReportingBody.subDisclosureReason.chkCapNSL);
}


if (!validation.isConditionalMandatory(strSumAndReportBodyPage.subReportingBody.subOtherInform.rdPreviousDisclosureW,1,strSumAndReportBodyPage.subReportingBody.subOtherInform.txtJfiuNo)){

errorMessage.push("JFIU Reference must be filled.");
}

if (!validation.isConditionalMandatory(strSumAndReportBodyPage.subReportingBody.subOtherInform.rdPreviousDisclosureW,1,strSumAndReportBodyPage.subReportingBody.subOtherInform.txtUrRefNo)){

errorMessage.push("Your Reference must be filled.");
}


//Check Per Subject
var noOfSubj= subjectPage.subSubjectEntity.instanceManager.count;
for (var i=0;i<noOfSubj;i++){
/*
if (!validation.isFilledSubjNameHKIDOtherID(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtFamilyName,xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtGivenName,xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtMiddleName,xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtChineseName,xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidAlpha, xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidDigit, xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidChkDigit, xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectOtherID.txtOtherIdNo)){

errorMessage.push("Subject"+(i+1) +  ": At least one highlighted field must be filled.");
}
*/

if (!validation.isValidLength(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtCCC1,4)){

errorMessage.push("Subject "+(i+1)+ ": "+ "CCC1 must be in length 4.");
}

if (!validation.isValidLength(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtCCC2,4)){

errorMessage.push("Subject "+(i+1)+ ": "+ "CCC2 must be in length 4.");
}

if (!validation.isValidLength(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtCCC3,4)){

errorMessage.push("Subject "+(i+1)+ ": "+ "CCC3 must be in length 4.");
}

if (!validation.isValidLength(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtCCC4,4)){

errorMessage.push("Subject "+(i+1)+ ": "+ "CCC4 must be in length 4.");
}

if (!validation.isValidLength(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtCCC5,4)){

errorMessage.push("Subject "+(i+1)+ ": "+ "CCC5 must be in length 4.");
}

if (!validation.isValidLength(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtCCC6,4)){

errorMessage.push("Subject "+(i+1)+ ": "+ "CCC6 must be in length 4.");
}

if (!validation.isValidDateFormat(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartB.dtDOB)||!validation.isValidDOB(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartB.dtDOB)){

errorMessage.push("Subject "+(i+1)+ ": "+ "Date of Birth is not in valid format [YYYY-MM-DD] or the values are out of range.");
}


if (!validation.isBeforeToday(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartB.dtDOB,"DOB")){

errorMessage.push("Subject "+(i+1)+ ": "+ "Date of Birth is not in valid format [YYYY-MM-DD] or the values are out of range.");
}

if (!validation.isValidHKID(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidAlpha, xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidDigit, xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidChkDigit)){
errorMessage.push("Subject "+(i+1)+ ": "+"HKID or Check-Digit is invalid.");
}

if (!validation.isValidHKIDFormat(xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidAlpha, xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidDigit, xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidChkDigit)){
errorMessage.push("Subject "+(i+1)+ ": "+"HKID is not in valid format [X999999 or XX999999].");
}

if (!xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidAlpha.isNull && !xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidDigit.isNull && xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subSubjectPartA.txtHkidChkDigit.isNull){
errorMessage.push("Subject "+(i+1)+ ": "+"HKID Check-Digit is missing.");
}


var curSubjNoOfEmail =xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subEmailList.subEmailDetail.instanceManager.count;
for (var j=0;j<curSubjNoOfEmail;j++){
var curSubjCurEmail= xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]").subEmailList.resolveNode("subEmailDetail["+j+"]").txtEmail;
if (!validation.isValidEmail(curSubjCurEmail)){
errorMessage.push("Subject "+(i+1)+"--"+  "Email "+ (j+1)+ " is not in valid format." );
}

}


} //end for loop


//Check per organization
var noOfOrg= organPage.subOrganEntity.instanceManager.count;

for (var i=0;i<noOfOrg;i++){
var curDtIncorporation= xfa.resolveNode("organPage.subOrganEntity["+i+"]").subOrganPartA.dtIncorporation;
if (!validation.isValidDateFormat(curDtIncorporation)){
errorMessage.push("Organization "+(i+1)+"--"+"Date of Incorporation is not in valid format [YYYY-MM-DD] or the values are out of range.");
}

var curOrgNoOfEmail =xfa.resolveNode("organPage.subOrganEntity["+i+"]").subEmailList.subEmailDetail.instanceManager.count;
for (var j=0;j<curOrgNoOfEmail;j++){
var curOrgCurEmail= xfa.resolveNode("organPage.subOrganEntity["+i+"]").subEmailList.resolveNode("subEmailDetail["+j+"]").txtEmail;
if (!validation.isValidEmail(curOrgCurEmail)){
errorMessage.push("Organization "+(i+1)+"--"+  "Email "+ (j+1)+ " is not in valid format." );
}
}

}
//Check per phone
var noOfPhone= phonePage.tabPhone.Row1.instanceManager.count;
for (var i=0;i<noOfPhone;i++){
var curPhone =xfa.resolveNode("phonePage.tabPhone.Row1["+i+"]").txtSubScriberNo;
if (!validation.isValidLengthPhone(curPhone,6)){
errorMessage.push("Phone "+(i+1)+  "'s subscriber number must be in length 6." );
}
}

//Check Per Account
var noOfAc= acTransPage.Account.subAccEntity.instanceManager.count;

for (var i=0;i<noOfAc;i++){
if (!validation.isValidDateFormat(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtOpenDt)||
!validation.isBeforeToday(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtOpenDt)||
!validation.isAfter1970(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtOpenDt)){

errorMessage.push("Account "+(i+1)+ ": "+ "Opening Date is not in valid format [YYYY-MM-DD] or the values are out of range.");
}

if (!validation.isValidDateFormat(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtCloseDt)||
!validation.isBeforeToday(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtCloseDt)||
!validation.isAfter1970(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtCloseDt)){

errorMessage.push("Account "+(i+1)+ ": "+ "Closing Date is not in valid format [YYYY-MM-DD] or the values are out of range.");
}

if (!validation.isValidDateFormat(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtAcBalanceDt)||
!validation.isBeforeToday(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtAcBalanceDt)||
!validation.isAfter1970(xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]").subAccPartA.dtAcBalanceDt)){

errorMessage.push("Account "+(i+1)+ ": "+ "Balance Date is not in valid format [YYYY-MM-DD] or the values are out of range.");
}
}


//Check Per Transaction
var noOfTransaction=acTransPage.SuspiciousTransaction.subTransactionEntity.instanceManager.count;

for (var i=0;i<noOfTransaction;i++){

if (!validation.isValidDateFormat(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtFrom)||
!validation.isAfter1970(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtFrom) ){
errorMessage.push("Transaction "+ (i+1)+": "+ "Transaction Date From is not in valid format [YYYY-MM-DD] or the values are out of range.");
}


if (!validation.isValidDateFormat(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtTo)||
!validation.isAfter1970(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtTo) ){
errorMessage.push("Transaction "+ (i+1)+": "+ "Transaction Date To is not in valid format [YYYY-MM-DD] or the values are out of range.");
}

if (!validation.isFrmDateBeforeToDate(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtFrom,xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtTo )){
errorMessage.push("Transaction "+ (i+1)+": "+ "Transaction Date To must be after Transaction Date From.");
}

}


for (var i=0;i<noOfTransaction;i++){
if ((xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtFrom.isNull&&
xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtTo.isNull)||
xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlSubject.isNull||
xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlTransactType.isNull||
xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlCurrency.isNull||
xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlCreditOrDebit.isNull||
xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.txtAmount.isNull	){

formatter.setErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtFrom);
formatter.setErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtTo);
formatter.setErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlSubject);
formatter.setErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlTransactType);
formatter.setErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlCurrency);
formatter.setErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlCreditOrDebit);
formatter.setErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.txtAmount);

errorMessage.push("Please fill in at least one transaction.");
break;
}
else {
formatter.clearErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtFrom);
formatter.clearErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.dtTo);
formatter.clearErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlSubject);
formatter.clearErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlTransactType);
formatter.clearErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlCurrency);
formatter.clearErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.ddlCreditOrDebit);
formatter.clearErrorBorder(xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+i+"]").subTransactionPartA.txtAmount);
break;
}
}


if (acTransPage.subTransactionTotal.txtTotalAmount.isNull||acTransPage.subTransactionTotal.txtTotalAmount.rawValue==""){
formatter.setErrorBorder(acTransPage.subTransactionTotal.txtTotalAmount);

errorMessage.push("Please fill in Total Amount of Suspicious Transactions Reported (in HKD).");
} else{
formatter.clearErrorBorder(acTransPage.subTransactionTotal.txtTotalAmount);
}



if (acTransPage.subTransactionTotal.txtTotalPeriod.isNull||acTransPage.subTransactionTotal.txtTotalPeriod.rawValue==""){
formatter.setErrorBorder(acTransPage.subTransactionTotal.txtTotalPeriod);

errorMessage.push("Please fill in Total Period covering the Suspicious Transactions (in days).");
} else{
formatter.clearErrorBorder(acTransPage.subTransactionTotal.txtTotalPeriod);
}

if (acTransPage.subTransactionTotal.txtDailyAverage.isNull||acTransPage.subTransactionTotal.txtDailyAverage.rawValue==""){
formatter.setErrorBorder(acTransPage.subTransactionTotal.txtDailyAverage);

errorMessage.push("Please fill in Daily Average of the Suspicious Transactions Reported.");
} else{
formatter.clearErrorBorder(acTransPage.subTransactionTotal.txtDailyAverage);
}


//Check Suspected Crimes page

if (!validation.atLeastOneSuspectedCrimes()){

errorMessage.push("Please check at least one suspected crime.");
}

if (!validation.isConditionalMandatory(suspectedCrimesPage.chkgpCategoriesOfOffencsByFATF.subPartA.subFraud.cbOthers,1,suspectedCrimesPage.chkgpCategoriesOfOffencsByFATF.subPartA.subFraud.subOthers.txtOthers)){

errorMessage.push("Suspected Crimes: Others (Please specify) must be filled.");
}

/*	if( suspectedCrimesPage.chkgpCategoriesOfOffencsByFATF.subMoneyLaundering.cbMoneyLauOthers.rawValue == 1 ) {
if( suspectedCrimesPage.subAddInfo.txtAdditInform.rawValue == "" ) {
formatter.setErrorBorder(suspectedCrimesPage.subAddInfo.txtAdditInform);
errorMessage.push("Please input additional information under Suspected Crimes.");
}
} else {
formatter.clearErrorBorder(suspectedCrimesPage.subAddInfo.txtAdditInform);
}		*/

//Check Suspicious Indicator Page

if (!validation.isChkedSuspiciousFund()){
errorMessage.push("Please check at least one suspicious indicator in Fund Movement Pattern.");
}
if (!validation.isChkedSuspiciousAccounts()){
errorMessage.push("Please check at least one suspicious indicator in Accounts.");
}
if (!validation.isChkedSuspiciousCustomerBg()){
errorMessage.push("Please check at least one suspicious indicator in Customer Background/Behavior.");
}
if (!validation.isChkedSuspiciousOthers()){
errorMessage.push("Please check at least one suspicious indicator in Others.");
}
if (!validation.isConditionalMandatory(suspiciousIndicatorPage.chkOthers.cbOthers,"OTHS",suspiciousIndicatorPage.chkOthers.txtOthers) ){
errorMessage.push("Suspicious Indicator: Others (Please specify) must be filled.");
}

//Check open source information

var noOfWebsites= openSourceInformation.subWebsite.instanceManager.count;

for (var i=0;i<noOfWebsites;i++){
if (!validation.isValidWebsite(xfa.resolveNode("openSourceInformation.subWebsite["+i+"]").txtWebsite)  ){
errorMessage.push("Website "+ (i+1)+ " is not in valid format.");
}
}


}

//group array of error messages into one single message
for (var i=0;i<errorMessage.length;i++){
if (i==0){
result = errorMessage[i]
}
else{
result+= '\r\n' + errorMessage[i];
}
}
if (result.length!=0){
//xfa.host.messageBox(result);
strSumAndReportBodyPage.SystemFields.isValidate.rawValue="FALSE";
} else{
strSumAndReportBodyPage.SystemFields.isValidate.rawValue="TRUE";
}
if (strSumAndReportBodyPage.SystemFields.isValidate.rawValue=="FALSE"){
xfa.host.messageBox(result);
}

//app.execMenuItem("Save");
                            if (strSumAndReportBodyPage.SystemFields.isValidate.rawValue=="TRUE"){
                            app.execMenuItem("SaveAs");
                            } else if (xfa.host.messageBox("You have not completed the form. Press \"Yes\" to proceed to save or press \"No\" to view the validation error.","Save Form",2,2)==4){
                            //data.saveHidden();
                            app.execMenuItem("SaveAs");
                            }
                            else{
                            btnValidate.execEvent("click");
                            }

if(this.rawValue=="true"){
                                txtInvestigatUnit.presence="visible";
                                txtRef.presence="visible";
                                Rectangle2.presence="visible";
                                vl2.presence="visible";
                                hl1.presence="visible";
                                formatter.clearErrorBorder(this);
                                }else{
                                txtInvestigatUnit.presence="hidden";
                                txtRef.presence="hidden";
                                Rectangle2.presence="hidden";
                                vl2.presence="hidden";
                                hl1.presence="hidden";
                                txtInvestigatUnit.rawValue = "";
                                txtRef.rawValue = "";
                                formatter.clearErrorBorder(txtInvestigatUnit);
                                formatter.clearErrorBorder(txtRef);
                                formatter.clearErrorBorder(this);
                                }

if (!validation.isConditionalMandatory(rdExistInvestigat,1,this)){
                                xfa.host.messageBox("Investigation unit must be filled.");
                                formatter.setErrorBorder(this);
                                }
                                else{
                                formatter.clearErrorBorder(this);
                                }

if (!validation.isConditionalMandatory(rdExistInvestigat,1,this)){
                                xfa.host.messageBox("Case Reference must be filled.");
                                formatter.setErrorBorder(this);
                                }
                                else{
                                formatter.clearErrorBorder(this);
                                }

if (!xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").txtFileName.isNull){

                                            var sAttachObjName = xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").subBtn.fileID.rawValue;
                                            event.target.exportDataObject({ cName: sAttachObjName, nLaunch: 2 });
                                            }

if (!xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").txtFileName.isNull){
                                            if (xfa.host.messageBox("Are you sure you wished to delete the file \""+xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").txtFileName.rawValue+"\" ?","",1,2)==4){

                                            event.target.removeDataObject(xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").subBtn.fileID.rawValue);
                                            NoOfAttachments.rawValue=xfa.resolveNode("fileList.fileDetails").instanceManager.count ;

                                            if (xfa.resolveNode("fileList.fileDetails").instanceManager.count>1){
                                            xfa.resolveNode('fileList._fileDetails').removeInstance(this.parent.parent.index);
                                            } else {
                                            xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").subBtn.fileID.rawValue="";
                                            xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").txtFileName.rawValue="";
                                            xfa.resolveNode("fileList.fileDetails["+ this.parent.parent.index +"]").subFileSize.txtFileSize.rawValue="";
                                            }

                                            }
                                            }

calculate.script:
var noOfRows=fileList.fileDetails.instanceManager.count;
var totalSize=0;
for (var i=0;i<noOfRows;i++){
totalSize += parseInt(xfa.resolveNode("fileList.fileDetails["+i+"]").subFileSize.txtFileSize.rawValue);
}

this.rawValue=totalSize;

event.script:
if (!validation.isValidLength(this,8)){
                            xfa.host.messageBox("Organization ID must be in length 8.");
                            }

if (!validation.isValidLength(this,2)){
                            xfa.host.messageBox("Reporting Officer ID must be in length 2.");

                            }

if (!validation.isValidEmail(this)){
                            xfa.host.messageBox("E-mail is not in valid format.");
                            }

if(this.rawValue=="true"){
                                txtJfiuNo.presence = "visible";
                                txtUrRefNo.presence = "visible";
                                Rectangle2.presence="visible";
                                vl2.presence="visible";
                                vl3.presence="visible";
                                vl4.presence="visible";

                                }else{
                                txtJfiuNo.rawValue = "";
                                txtJfiuNo.presence = "hidden";
                                txtUrRefNo.rawValue = "";
                                txtUrRefNo.presence = "hidden";
                                Rectangle2.presence="hidden";
                                vl2.presence="hidden";
                                vl3.presence="hidden";
                                vl4.presence="hidden";
                                }

if (!validation.isConditionalMandatory(rdPreviousDisclosureW,1,this)){
                                xfa.host.messageBox("JFIU Ref. No must be filled.");
                                formatter.setErrorBorder(this);
                                }
                                else{
                                formatter.clearErrorBorder(this);
                                }

if (!validation.isConditionalMandatory(rdPreviousDisclosureW,1,this)){
xfa.host.messageBox("Your Ref. No must be filled.");
formatter.setErrorBorder(this);
}
else{
formatter.clearErrorBorder(this);
}

if (xfa.host.messageBox('Would you like to delete this subject?',"",1,2)==4){
                                //removeID
                                xfa.resolveNode("subSubjectEntity["+this.parent.parent.index+"]").subSubjectPartA.txtPersonID.rawValue="";
                                //update linked accounts and organizations
                                data.updateRelatedPerson();

                                if (subSubjectEntity.instanceManager.count>1){
                                this.resolveNode('entityLists.subSubjectList.subjectList._Row1').removeInstance(this.parent.parent.index);
                                this.resolveNode('subjectPage._subSubjectEntity').removeInstance(this.parent.parent.index);
                                }else{
                                xfa.host.resetData(subSubjectEntity.somExpression);
                                subSubjectOtherID.instanceManager.setInstances(1);
                                subEmailList.subEmailDetail.instanceManager.setInstances(1);
                                //data.updateRelatedPerson();
                                }
                                }

	if (!this.isNull){
                                this.rawValue=this.rawValue.toUpperCase();
                                }
                                //update linked accounts and organizations
