variables.script:
function isValidLength(field,length){
if (!field.isNull&&field.rawValue!=""&&field.rawValue.length<length){
formatter.setErrorBorder(field);
return false;
}
formatter.clearErrorBorder(field);
return true;
}
function isValidLengthPhone(field,length){
if (!field.isNull&&field.rawValue.length<length){
formatter.setErrorBorderWithBorder(field);
return false;
}
formatter.clearErrorFieldWithBorder(field);
return true;
}
function isValidDateFormat(date){
if(date.isNull){
formatter.clearErrorBorder(date);
return true;
}
var year=parseInt(date.rawValue.substring(0,4));
var month=parseInt(date.rawValue.substring(5,7));
var day=parseInt(date.rawValue.substring(8,10));


if (date.rawValue.length==10&&date.rawValue.substring(4,5)=="-"&&date.rawValue.substring(7,8)=="-" ){
if (year<1900||month<1||month>12||day<1||day>31){
formatter.setErrorBorder(date);
return false;
}
if ((month==4||month==6||month==9||month==11)&&day==31){
formatter.setErrorBorder(date);
return false;
}
if (month==2&& (year%4)>0&& day>=29){
formatter.setErrorBorder(date);
return false;
}
}
else{
formatter.setErrorBorder(date);
return false;
}
formatter.clearErrorBorder(date);
return true;
}

function isAfter1970(date){
if (!date.isNull&& date.rawValue<"1970-01-01"){
formatter.setErrorBorder(date);
return false;
}
formatter.clearErrorBorder(date);
return true;
}

function isValidWebsite(website){
var r=/[-a-zA-Z0-9@:%._\+~#=]{2,256}\.[a-z]{2,6}\b([-a-zA-Z0-9@:%_\+.~#?&\/=]*)/ ;

if( !website.isNull && !r.test(website.rawValue)){
formatter.setErrorBorder(website);
return false;
}
else{
