function isValidSubmitNo(num){
if (num.isNull||num==""){
return true;
}
else{
var subNoDate=new Date (num.rawValue.substring(8,12),num.rawValue.substring(12,14)-1,num.rawValue.substring(14,16)  );
var today=new Date();

if (subNoDate>today){
xfa.host.messageBox("Submission Number date should not be after today.");
return false;
}

else if (subNoDate< new Date(1970,0,1,0,0,0)){
xfa.host.messageBox("Submission Number is out of range.");
return false;
}

var patt=/[^0-9]/g;
if (num.rawValue.substring(8,16).match(patt).length>0){
xfa.host.messageBox("Submission Number is not in valid format [XXX99999YYYYMMDD9999].");
return false;
}
}
}
