function checkCertExpiryDate(){
var messageArray=[];
var message="";

if (!STR.strSumAndReportBodyPage.SystemFields.certExpiryDate.isNull&&STR.strSumAndReportBodyPage.SystemFields.certExpiryDate.rawValue!=""){
var certs= STR.strSumAndReportBodyPage.SystemFields.certExpiryDate.rawValue.split(",");
var today = data.genDate();

for (var i =0;i<certs.length;i++){
var curCertName= certs[i].split(":")[0];
var curExpiryDate= certs[i].split(":")[1];

if (curExpiryDate< today){
messageArray.push("The certificate of "+curCertName+" was expired [Expiry Date: "+ curExpiryDate+ "].");
}
}

//group array of error messages into one single message
for (var i=0;i<messageArray.length;i++){
if (i==0){
message= messageArray[i];
}
else{
message+= '\r\n' + messageArray[i];
}
}
if (message.length>0){
message+= '\r\n\r\n'+"The Form will be closed automatically.";
}
return message;
}

}


