check.rawValue=checkID;
}
}
}


function isValidHKIDFormat(alpha,digit,check){
if (alpha.isNull || digit.isNull){
return true;
}

var regAlpha= /[A-Z]{1,2}/;

if (!regAlpha.test(alpha.rawValue)){
formatter.setErrorBorder(alpha);
}else {
formatter.clearErrorBorder(alpha);
}
var reg = /[0-9]{6}/;


if (!reg.test(digit.rawValue) ){
formatter.setErrorBorder(digit);
}else {
formatter.clearErrorBorder(digit);
}

if (regAlpha.test(alpha.rawValue) &&	reg.test(digit.rawValue) ){
return true;
} else{
return false;
}

}

function getDateFromTextField(textField){
var year = parseInt(textField.rawValue.substring(0,4));
var month = parseInt(textField.rawValue.substring(5,7))-1;
var day = parseInt(textField.rawValue.substring(8,10));

if (month<10){
month= "0"+month;
}
if (day<10){
day= "0"+day;
}

return new Date (year,month,day);
}

function getTimeFromTextField(textField){
var hours = textField.rawValue.substring(0,2);
if (hours.toString().length==1){
hours="0" +hours;
}
var minutes = textField.rawValue.substring(3,5);
if (minutes.toString().length==1){
minutes="0" +minutes;
}
return [hours,minutes];
}


function isBeforeToday(date){
var today=new Date();
if (!date.isNull){
var chkDate= getDateFromTextField(date);

if (chkDate>today){ //Invalid date
formatter.setErrorBorder(date);
return false;

} else {
formatter.clearErrorBorder(date);
return true;
}
}
else{
formatter.clearErrorBorder(date);
return true;
}

}


function isFrmTimeLessThanToTime(dtFrom, dtTo, timeFrom, timeTo){
if ( dtFrom.isNull || dtTo.isNull || timeFrom.isNull ||timeTo.isNull){
return true;
}
else{

var yearFrom= dtFrom.rawValue.substring(0,4);
var monthFrom=dtFrom.rawValue.substring(5,7)-1;
var dayFrom=dtFrom.rawValue.substring(8,10);
var hourFrom=timeFrom.rawValue.substring(0,2);
var minutesFrom=timeFrom.rawValue.substring(3,5);
var dateFrom= new Date(yearFrom,monthFrom,dayFrom,hourFrom,minutesFrom,0);

var yearTo= dtTo.rawValue.substring(0,4);
var monthTo=dtTo.rawValue.substring(5,7)-1;
var dayTo=dtTo.rawValue.substring(8,10);
var hourTo=timeTo.rawValue.substring(0,2);
var minutesTo=timeTo.rawValue.substring(3,5);
var dateTo= new Date(yearTo,monthTo,dayTo,hourTo,minutesTo);

var interval = dateTo.valueOf() - dateFrom.valueOf();
if(interval<0){
formatter.setErrorBorder(dtFrom);
formatter.setErrorBorder(dtTo);
formatter.setErrorBorder(timeFrom);
formatter.setErrorBorder(timeTo);
return false;
}

else{
formatter.clearErrorBorder(dtFrom);
formatter.clearErrorBorder(dtTo);
formatter.clearErrorBorder(timeFrom);
formatter.clearErrorBorder(timeTo);
return true;
}
}
}

function isFrmDateBeforeToDate(fromDate,toDate){
if ( (!fromDate.isNull)&& (!toDate.isNull) && toDate.rawValue<fromDate.rawValue){
formatter.setErrorBorder(fromDate);
formatter.setErrorBorder(toDate);
return false;
}
else{
formatter.clearErrorBorder(fromDate);
formatter.clearErrorBorder(toDate);
return true;
}

}

