function isValidEmail(email){
var r = /^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
if( !email.isNull && !r.test(email.rawValue)){
formatter.setErrorBorder(email);
return false;
}
else{
formatter.clearErrorBorder(email);
return true;
}
}

function isValidTime(date){
if(date.isNull){
formatter.clearErrorBorder(date);
return true;
}
var hours=parseInt(date.rawValue.substring(0,2));
var mins=parseInt(date.rawValue.substring(3,5));
var secs=parseInt(date.rawValue.substring(6,8));


if (date.rawValue.length==8&&date.rawValue.substring(2,3)==":"&&date.rawValue.substring(5,6)==":" ){
if (hours<0||hours>24){
formatter.setErrorBorder(date);
return false;
}
if (mins<0||mins>59){
formatter.setErrorBorder(date);
return false;
}
if (secs<0||secs>59){
formatter.setErrorBorder(date);
return false;
}
}
else{
formatter.setErrorBorder(date);
return false;
}
formatter.clearErrorBorder(date);
return true;
}

