if (oDetails.nodes.item(i).name.slice(-8) == "Currency" && oDetails.nodes.item(i).rawValue == "HKD"){
//do nth
sDtlFields = sDtlFields + "\n" + oDetails.nodes.item(i).name + "|true";
}else if(oDetails.nodes.item(i).name == "ddlCreditOrDebit" && oDetails.nodes.item(i).rawValue == "+"){
//do nth
sDtlFields = sDtlFields + "\n" + oDetails.nodes.item(i).name + "|true";
}else{
//return false;
sDtlFields = sDtlFields + "\n" + oDetails.nodes.item(i).name + "|false";
return sDtlFields;
}
}
}

}
}else{
if (oDetails.nodes.item(i).className == "exclGroup"){
if (oDetails.nodes.item(i).name == "rdGender"){
//check is default "U"
}
sDtlFields = sDtlFields + "\n" + oDetails.nodes.item(i).name + "|" + oDetails.nodes.item(i).rawValue;

}
}
}

//return true;
return sDtlFields;
}

function isSectionEmpty2(dString){
var sDtlFields="";
var oNodes = xfa.resolveNodes(dString);
var nNodesLength = oNodes.length;
sDtlFields = "Total loop: " + nNodesLength;

for (var nNodeCount = 0; nNodeCount < nNodesLength; nNodeCount++) {
//sDtlFields = sDtlFields + ";\n*" + oNodes.item(nNodeCount).somExpression;
sDtlFields = sDtlFields + ";\n*" + isSubSectionEmpty2(oNodes.item(nNodeCount).somExpression);
/*if (!isSubSectionEmpty(oNodes.item(nNodeCount).somExpression)){
return false;
}*/
}

//return true;
return sDtlFields;
}

function loadFieldData(subForm,index,field){
                /*USAGE:
                partA[index].partB
                exmaple path= "STR.subjectPage.subSubjectEntity[index].subSubjectPartA.txtFamilyName";*/

                var subjectList=[];
                //for(i=0; i<instanceCount; i++) {
                //xfa.host.messageBox(instanceCount.toStringcl());

                var fName = subForm+ "["+ index +"]."+field;
                var fValue = xfa.resolveNode(fName).rawValue;
                subjectList.push(fValue);
                //}
                return subjectList.toString();
                }


                function loadDataArray(subForm,index,subEntity,type){
                var curEntity=xfa.resolveNode(subForm+ "["+ index +"]");
                var instanceCount= curEntity.resolveNode(subEntity).instanceManager.count;
                var entityList=[];
                for(i=0; i<instanceCount; i++) {
                switch(type){
                case 'personName':
                var fValue = curEntity.resolveNode("subRelatedPerson["+i+"]").txtRelatedPerson.rawValue;
                entityList.push(fValue);
                break;

                case 'personRole':
                if (!curEntity.resolveNode("subRelatedPerson["+i+"]").ddlRelatedPersonRole.isNull)	{
                var fValue = curEntity.resolveNode("subRelatedPerson["+i+"]").ddlRelatedPersonRole.rawValue ;
                }
                if (!curEntity.resolveNode("subRelatedPerson["+i+"]").txtRelatedPersonRoleOthers.isNull)	{
                fValue += curEntity.resolveNode("subRelatedPerson["+i+"]").txtRelatedPersonRoleOthers.rawValue ;
                }
                entityList.push(fValue);
                break;


                case 'organName':
                var fValue = curEntity.resolveNode("subRelatedCompany["+i+"]").txtRelatedCompany.rawValue;
                entityList.push(fValue);
                break;

                case 'organRole':
                if (!curEntity.resolveNode("subRelatedCompany["+i+"]").ddlRelatedCompanyRole.isNull){
                var fValue = curEntity.resolveNode("subRelatedCompany["+i+"]").ddlRelatedCompanyRole.rawValue;
                }
                if (!curEntity.resolveNode("subRelatedCompany["+i+"]").txtRelatedCompanyRoleOthers.isNull){
                fValue += curEntity.resolveNode("subRelatedCompany["+i+"]").txtRelatedCompanyRoleOthers.rawValue;
                }
                entityList.push(fValue);
                break;

                }
                }
                return (entityList.toString()).replace(/,/g,"\r\n");
                }


                function clonePhoneFromEntity(srcObject, destObject){
                var curPhone="";
                var validate=true;

                //Get linked id list
                var count=0;
                var noOfRows = srcObject.instanceManager.count;
                var phoneArray=[];

                //validation
                for(var i=0; i<noOfRows;i++){
                phoneRow = xfa.resolveNode("STR.phonePage.tabPhone.Row1[" + i  + "]");
                if(phoneRow.txtSubScriberNo.isNull){
                xfa.host.messageBox("Row "+ (i+1) +" Subscriber must be filled.");
                validate = false;
                xfa.host.setFocus(phoneRow.txtSubScriberNo);
                return false;
                }
                else if (phoneRow.txtSubScriberNo.rawValue.length<6){
                xfa.host.messageBox("Row "+ (i+1) +" Subscriber Number must have at least 6 digits.");
                validate = false;
                xfa.host.setFocus(phoneRow.txtSubScriberNo);
                return false;
                }
                }

                // count checked rows
                for(var i=0; i<noOfRows;i++){
                var phoneRow = xfa.resolveNode("STR.phonePage.tabPhone.Row1[" + i  + "]");
                if(phoneRow.subChkBox.chkLinked.rawValue==1){
                count++;
                }
                }

                //set rows
                if (count > 0) {
                destObject.instanceManager.setInstances(count);

                //set ID from entity to subject
                var chkPhoneIndex=0;
                for (var i = 0; i < noOfRows; i++) {
                phoneRow = xfa.resolveNode("STR.phonePage.tabPhone.Row1[" + i + "]");
                if (phoneRow.subChkBox.chkLinked.rawValue == 1) {

                //make sure subject phone id list has the same number as phone entity phone id list
                while (chkPhoneIndex<count){
                var newRow = destObject.resolveNode("PhoneNumDetail[" + chkPhoneIndex + "]");
                newRow.ChildId.rawValue = phoneRow.subBtn.txtPhoneId.rawValue;
                chkPhoneIndex++;

                //convert phone number to String
                curPhone = "";
                if (srcObject.resolveNode("Row1[" + i + "]").txtCountryCode.isNull) {
                curPhone += "";
                } else {
                curPhone += srcObject.resolveNode("Row1[" + i + "]").txtCountryCode.rawValue;
                }


                if (srcObject.resolveNode("Row1[" + i + "]").txtAreaCode.isNull) {
                curPhone += "";
                } else if (curPhone.length == 0) {
                curPhone += srcObject.resolveNode("Row1[" + i + "]").txtAreaCode.rawValue;
                } else {
                curPhone += "-" + srcObject.resolveNode("Row1[" + i + "]").txtAreaCode.rawValue;
                }

                if (srcObject.resolveNode("Row1[" + i + "]").txtSubScriberNo.isNull) {
                curPhone += "";
                xfa.host.messageBox("Row "+ (i+1) +" Subscriber must be filled.");
                validate = false;
                break;
                } else if (curPhone.length == 0) {
                curPhone += srcObject.resolveNode("Row1[" + i + "]").txtSubScriberNo.rawValue;
                } else {
                curPhone += "-" + srcObject.resolveNode("Row1[" + i + "]").txtSubScriberNo.rawValue;
                }

                if (srcObject.resolveNode("Row1[" + i + "]").txtExtension.isNull) {
                curPhone += "";
                } else if (curPhone.length == 0) {
                curPhone += srcObject.resolveNode("Row1[" + i + "]").txtExtension.rawValue;
                } else {
                curPhone += "-" + srcObject.resolveNode("Row1[" + i + "]").txtExtension.rawValue;
                }
                if (!curPhone.length == 0) {
                phoneArray.push(curPhone);
                }
                break;

                }
                } else {continue;}
                }	//end for loop



                if (phoneArray.length>0){
                //xfa.host.messageBox(phoneArray.toString());
                xfa.resolveNode(phonePage.subHeader.txtPhone.rawValue).rawValue = phoneArray.toString();
                }
                }else {
                xfa.resolveNode(phonePage.subHeader.txtPhone.rawValue).rawValue = phoneArray.toString();
                destObject.instanceManager.setInstances(1);
                destObject.resolveNode("PhoneNumDetail[0]").ChildId.rawValue="";
                }

                if (validate == true) {
                for (var i=0;i<noOfRows;i++){
                xfa.resolveNode("STR.phonePage.tabPhone.Row1["+i+"]").subChkBox.chkLinked.rawValue=0;
                }

                xfa.host.setFocus(phonePage.subHeader.targetSubject.rawValue);
                pageUtilities.loadPreviousLocation();
                return true;
                }

                }

                function showChkPhone(srcObject, destObject){
                var noOfPhones= srcObject.instanceManager.count;
                var noOfPhoneEntity=destObject.instanceManager.count;

                for (var j=0;j<noOfPhones;j++){
                for (var i=0;i<noOfPhoneEntity;i++){
                if (srcObject.resolveNode("PhoneNumDetail["+j+"]").ChildId.rawValue==destObject.resolveNode("Row1["+i+"]").subBtn.txtPhoneId.rawValue){
                destObject.resolveNode("Row1["+i+"]").subChkBox.chkLinked.rawValue=1;
                }
                }
                }
                }

                function updatePhoneSubj(){

                var curPhone="";
                var phoneArray=[];
                var phoneIdArray=[];

                //count total number of subjects
                var subjCount=xfa.resolveNode("subjectPage.subSubjectEntity").instanceManager.count;

                for (var i=0;i<subjCount;i++){
                var curSubj=xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]");
                phoneArray=[];
                phoneIdArray=[];

                //count current subject's number of phones
                var subjPhoneCount=curSubj.resolveNode("subPhone.PhoneNumList.PhoneNumDetail").instanceManager.count;

                for (var j=0;j<subjPhoneCount;j++){
                //count number of phones in phone entity
                var phoneEntityCount=xfa.resolveNode("phonePage.tabPhone.Row1").instanceManager.count;

                for (var k=0;k<phoneEntityCount;k++){
                var curSubjPhoneId=curSubj.subPhone.resolveNode("PhoneNumList.PhoneNumDetail["+j+"]").ChildId.rawValue;
                var curPhoneEntity=xfa.resolveNode("phonePage.tabPhone.Row1["+k+"]");
                var curPhoneId=curPhoneEntity.subBtn.txtPhoneId.rawValue;

                if (curSubjPhoneId!=null&&curPhoneId!=null&&(curSubjPhoneId==curPhoneId)){
                phoneIdArray.push(curPhoneId);
                //convert phone number to String
                curPhone = "";
                if (curPhoneEntity.txtCountryCode.isNull) {
                curPhone += "";
                } else {
                curPhone += curPhoneEntity.txtCountryCode.rawValue;
                }


                if (curPhoneEntity.txtAreaCode.isNull) {
                curPhone += "";
                } else if (curPhone.length == 0) {
                curPhone += curPhoneEntity.txtAreaCode.rawValue;
                } else {
                curPhone += "-" + curPhoneEntity.txtAreaCode.rawValue;
                }

                if (curPhoneEntity.txtSubScriberNo.isNull) {
                curPhone += "";
                //xfa.host.messageBox("Row "+ (i+1) +" Subscriber must be filled.");
                //validate = false;
                //break;

                } else if (curPhone.length == 0) {
                curPhone += curPhoneEntity.txtSubScriberNo.rawValue;
                } else {
                curPhone += "-" + curPhoneEntity.txtSubScriberNo.rawValue;
                }

                if (curPhoneEntity.txtExtension.isNull) {
                curPhone += "";
                } else if (curPhone.length == 0) {
                curPhone += curPhoneEntity.txtExtension.rawValue;
                } else {
                curPhone += "-" + curPhoneEntity.txtExtension.rawValue;
                }
                if (!curPhone.length == 0) {
                phoneArray.push(curPhone);
                }
                }

                }//end phone entity loop
                }//end subject phone loop

                //reset related phone id list and related phone list
                curSubj.subPhone.txtPhone="";
                curSubj.subPhone.PhoneNumList.PhoneNumDetail.instanceManager.setInstances(1);
                curSubj.subPhone.PhoneNumList.PhoneNumDetail.ChildId.rawValue="";

                if (phoneArray.length>0){
                curSubj.subPhone.txtPhone=phoneArray.toString();
