                curSubj.subPhone.PhoneNumList.PhoneNumDetail.instanceManager.setInstances(phoneIdArray.length);

                for (var l=0;l<phoneIdArray.length;l++){
                curSubj.subPhone.PhoneNumList.resolveNode("PhoneNumDetail["+l+"]").ChildId.rawValue= phoneIdArray[l];
                }
                }
                }//end subject entity loop
                }

