                function refreshCCC(){
                var noOfSubject=subjectPage.subSubjectEntity.instanceManager.count;
                for (var i=0;i<noOfSubject;i++){
                var curSubject= xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]");
                //reset all CCC fields
                curSubject.subSubjectPartA.txtCCC1.rawValue="";
                curSubject.subSubjectPartA.txtCCC2.rawValue="";
                curSubject.subSubjectPartA.txtCCC3.rawValue="";
                curSubject.subSubjectPartA.txtCCC4.rawValue="";
                curSubject.subSubjectPartA.txtCCC5.rawValue="";
                curSubject.subSubjectPartA.txtCCC6.rawValue="";

                var curSubjectNoOfCCC=curSubject.subSubjectPartA.ChineseCommercialCode.FourDigitCode.instanceManager.count;
                for (var j=0;j<curSubjectNoOfCCC;j++){
                var curField="subSubjectPartA.txtCCC"+(j+1);
                curSubject.resolveNode(curField).rawValue= curSubject.subSubjectPartA.ChineseCommercialCode.resolveNode("FourDigitCode["+j+"]").data.rawValue;
                }
                }
                }
                function refreshHKID(){
                var noOfSubj=subjectPage.subSubjectEntity.instanceManager.count;

                for (var i=0;i<noOfSubj;i++){
                var curSubj= xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]");

                var curSubjHkidIdentifier= curSubj.subSubjectPartA.txtHkidIdentifier;

                if (!curSubjHkidIdentifier.isNull&& curSubjHkidIdentifier.rawValue!=""){
                if (curSubjHkidIdentifier.rawValue.length<=7){
                curSubj.subSubjectPartA.txtHkidAlpha.rawValue= curSubjHkidIdentifier.rawValue.substring(0,1);
                curSubj.subSubjectPartA.txtHkidDigit.rawValue= curSubjHkidIdentifier.rawValue.substring(1,7);
                }
                else{
                curSubj.subSubjectPartA.txtHkidAlpha.rawValue= curSubjHkidIdentifier.rawValue.substring(0,2);
                curSubj.subSubjectPartA.txtHkidDigit.rawValue= curSubjHkidIdentifier.rawValue.substring(2,8);
                }
                }
                }
                }
                function refreshLocalOverseaCompany(){
                var noOfOrgan= organPage.subOrganEntity.instanceManager.count;

                for (var i=0;i<noOfOrgan;i++){
                var curOrgan=xfa.resolveNode("organPage.subOrganEntity["+i+"]");
                if (curOrgan.subOrganPartA.chkLocalCompany.rawValue=="true"){
                curOrgan.subOrganPartA.txtBr.access="open";
                curOrgan.subOrganPartA.txtCr.access="open";
                curOrgan.subOrganPartA.txtPl.access="open";
                }
                if (curOrgan.subOrganPartA.chkOverseaCompany.rawValue=="true"){
                curOrgan.subOrganPartA.ddlCountry.access="open";
                curOrgan.subOrganPartA.txtRegNo.access="open";
                }
                }
                }

