                function cloneAddressFromEntity(srcObject, destObject){

                //Get linked id list
                var count=0;
                var noOfAddress = srcObject.instanceManager.count;

                //destObject=xfa.resolveNode(destObject+ ".subAddress[0].AddressList[0].AddressDetail[0]");

                // count checked rows
                for(var i=0; i<noOfAddress;i++){
                var addressRow = xfa.resolveNode("STR.addressPage.tabAddress.Row1[" + i  + "]");
                if(addressRow.subChkBox.chkLinked.rawValue==1){
                count++;
                }
                }

                //set counted rows
                if (count > 0) {
                destObject.instanceManager.setInstances(count);
                xfa.resolveNode(addressPage.subHeader.targetSubject.rawValue).subAddress.instanceManager.setInstances(count);

                //set ID from entity to subject
                var chkAddressIndex=0;
