                if (addressRow.subChkBox.chkLinked.rawValue == 1) {

                //make sure subject phone id list has the same number as phone entity phone id list
                while (chkAddressIndex<count){
                var newRow = destObject.resolveNode("AddressDetail[" + chkAddressIndex + "]");
