                var newAddressRow= xfa.resolveNode(addressPage.subHeader.targetSubject.rawValue).resolveNode("subAddress["+chkAddressIndex+"]");
                newAddressRow.txtAddress.rawValue = addressRow.subBtnAddress.txtAddress.rawValue;
                chkAddressIndex++;
