                function updateAddressSubj(){
                var subjAddressArray=[];
                var subjAddressIdArray=[];

                //count total number of subjects
                var subjCount=xfa.resolveNode("subjectPage.subSubjectEntity").instanceManager.count;
                //xfa.host.messageBox(subjCount.toString()+"subjects found");

                for (var i=0;i<subjCount;i++){
                var curSubj=xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]");

                //count current subject's number of address id
                var subjAddressCount=curSubj.resolveNode("subAddress.AddressList.AddressDetail").instanceManager.count;
                subjAddressArray=[];
                subjAddressIdArray=[];
                //xfa.host.messageBox(subjAddressCount.toString()+"addressess found");

                for (var j=0;j<subjAddressCount;j++){
                //count number of addresses in address entity
                var addressEntityCount=xfa.resolveNode("addressPage.tabAddress.Row1").instanceManager.count;

                for (var k=0;k<addressEntityCount;k++){
                var curSubjAddressId=curSubj.subAddress.resolveNode("AddressList.AddressDetail["+j+"]").ChildId.rawValue;
                var curAddressEntity=xfa.resolveNode("addressPage.tabAddress.Row1["+k+"]");
                var curAddressId=curAddressEntity.subBtn.txtAddressId.rawValue;

                if (curSubjAddressId!=null&&curAddressId!=null&&(curSubjAddressId==curAddressId)){
                subjAddressIdArray.push(curAddressId);
                subjAddressArray.push(curAddressEntity.subBtnAddress.txtAddress.rawValue);
                break;
                }
                } //end address entity loop
                }//end subjAddress loop
                //reset related address id list and related address list
                curSubj.subAddress.instanceManager.setInstances(1);
                curSubj.subAddress.txtAddress.rawValue="";

                curSubj.subAddress.AddressList.AddressDetail.instanceManager.setInstances(1);
                curSubj.subAddress.AddressList.AddressDetail.ChildId.rawValue="";

                if (subjAddressIdArray.length>0){
                curSubj.subAddress.AddressList.AddressDetail.instanceManager.setInstances(subjAddressIdArray.length);

                //Set the new address id into the subject
                for (var l=0;l<subjAddressIdArray.length;l++){
                curSubj.subAddress.AddressList.resolveNode("AddressDetail["+l+"]").ChildId.rawValue=subjAddressIdArray[l];
                }
                }
                if (subjAddressArray.length>0){
                curSubj.subAddress.instanceManager.setInstances(subjAddressArray.length);

                //set the new address into the subject
                for (var l=0;l<subjAddressArray.length;l++){
                curSubj.resolveNode("subAddress["+l+"]").txtAddress.rawValue=subjAddressArray[l];
                }
                }
                }//end subj entity loop
                }

                function updateAddressOrg(){
                var organAddressArray=[];
                var organAddressIdArray=[];

                //count total number of organizations
                var orgCount=xfa.resolveNode("organPage.subOrganEntity").instanceManager.count;

                for (var i=0;i<orgCount;i++){
                var curOrg=xfa.resolveNode("organPage.subOrganEntity["+i+"]");

                //count current organization's number of addresses
                var orgAddressCount=curOrg.resolveNode("subAddress.AddressList.AddressDetail").instanceManager.count;
                organAddressArray=[];
                organAddressIdArray=[];

                for (var j=0;j<orgAddressCount;j++){
                //count number of addresses in address entity
                var addressEntityCount=xfa.resolveNode("addressPage.tabAddress.Row1").instanceManager.count;

                for (var k=0;k<addressEntityCount;k++){
                var curOrgAddressId=curOrg.resolveNode("subOrganEntity["+i+"]").subAddress.resolveNode("AddressList.AddressDetail["+j+"]").ChildId.rawValue;
                var curAddressEntity=xfa.resolveNode("addressPage.tabAddress.Row1["+k+"]");
                var curAddressId=curAddressEntity.subBtn.txtAddressId.rawValue;

                if (curOrgAddressId!=null&&curAddressId!=null&&(curOrgAddressId==curAddressId)){
                organAddressIdArray.push(curAddressId);
                organAddressArray.push(curAddressEntity.subBtnAddress.txtAddress.rawValue);
                //curOrg.resolveNode("subAddress["+j+"]").txtAddress.rawValue=curAddressEntity.subBtnAddress.txtAddress.rawValue;
                break;
                }
                }//end address entity loop
                }//end organization address loop

                //reset related address id list and related address list
                curOrg.subAddress.instanceManager.setInstances(1);
                curOrg.subAddress.txtAddress.rawValue="";

                curOrg.subAddress.AddressList.AddressDetail.instanceManager.setInstances(1);
                curOrg.subAddress.AddressList.AddressDetail.ChildId.rawValue="";

                if (organAddressIdArray.length>0){
                curOrg.subAddress.AddressList.AddressDetail.instanceManager.setInstances(organAddressIdArray.length);

                for (var l=0;l<organAddressIdArray.length;l++){
                curOrg.subAddress.AddressList.resolveNode("AddressDetail["+l+"]").ChildId.rawValue=organAddressIdArray[l];
                }
                }

                if  (organAddressArray.length>0){
                curOrg.subAddress.instanceManager.setInstances(organAddressArray.length);

                for (var l=0;l<organAddressArray.length;l++){
                curOrg.resolveNode("subAddress["+l+"]").txtAddress.rawValue=organAddressArray[l];
                }
                }

                }//end organization loop
                }

                function cloneSubjectFromEntity(srcObject, destObject,targetOrgan,targetAccount){

                //var validate=true;
                var type="";
                if ((!targetOrgan.isNull)&&targetOrgan.rawValue!=""){
                type="organ";
                }	else if ((!targetAccount.isNull)&&targetAccount.rawValue!=""){
                type="account";
                }

                //Get linked id list
                var count=0;
                var noOfSubject = srcObject.instanceManager.count;
                //destObject=xfa.resolveNode(destObject+ ".subAddress[0].AddressList[0].AddressDetail[0]");

                // count checked rows

                for(var i=0; i<noOfSubject;i++){
                var subjectRow = xfa.resolveNode("STR.entityLists.subSubjectList.subjectList.Row1[" + i  + "]");
                if(subjectRow.subChkBox.chkLinked.rawValue==1){
                count++;
                }
