                //set checked rows
                if (count > 0) {
                destObject.instanceManager.setInstances(count);
                switch(type){
                case "organ":
                xfa.resolveNode(entityLists.subSubjectList.targetOrgan.rawValue).subRelatedPerson.instanceManager.setInstances(count);
                break;

