                if (subjectRow.subChkBox.chkLinked.rawValue == 1) {

                //make sure subject subject id list has the same number as subject entity list
                while (chkSubjectIndex<count){
                var newRow = destObject.resolveNode("PersonDetail[" + chkSubjectIndex + "]");
                newRow.ChildId.rawValue = subjectRow.subBtn.txtSubjectId.rawValue;
                switch (type){
                case "organ":
                var newSubjectRow= xfa.resolveNode(entityLists.subSubjectList.targetOrgan.rawValue).resolveNode("subRelatedPerson["+chkSubjectIndex+"]");
                newSubjectRow.txtRelatedPerson.rawValue = subjectRow.txtEnglishName.rawValue;
