                newSubjectRow.txtRelatedPerson.rawValue = subjectRow.txtEnglishName.rawValue;
                chkSubjectIndex++;
                break;
                }
                break;
                } //end while loop
                } else {
                continue;
                }
                }	//end for loop
                }
                //count is 0, no person is linked
                else {
                destObject.instanceManager.setInstances(1);
                switch (type){
                case "organ":
                xfa.resolveNode(entityLists.subSubjectList.targetOrgan.rawValue).subRelatedPerson.instanceManager.setInstances(1);
                break;

                case "account":
                xfa.resolveNode(entityLists.subSubjectList.targetAccount.rawValue).subRelatedPerson.instanceManager.setInstances(1);
                break;

