                //reset the checkboxes
                for (var i=0;i<noOfSubject;i++){
                xfa.resolveNode("STR.entityLists.subSubjectList.subjectList.Row1["+i+"]").subChkBox.chkLinked.rawValue=0;
                }
                //}
                }

