                function refreshAccount(){

                var acCount= acTransPage.Account.subAccEntity.instanceManager.count;

                for (var i=0;i<acCount;i++){
                var curAc=xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]");
                // refresh account balance +/- drop down list

                if (parseFloat(curAc.subAccPartA.txtAcBalanceHidden.rawValue)<0){
                curAc.subAccPartA.ddlCreditOrDebit.rawValue="-";
                curAc.subAccPartA.txtAcBalance.rawValue=parseFloat(curAc.subAccPartA.txtAcBalanceHidden.rawValue)*-1;
                }else{
                curAc.subAccPartA.ddlCreditOrDebit.rawValue="+";
                curAc.subAccPartA.txtAcBalance.rawValue=parseFloat(curAc.subAccPartA.txtAcBalanceHidden.rawValue);
                }
                }
                }
                function refreshTransaction(){

                var trxCount=acTransPage.SuspiciousTransaction.subTransactionEntity.instanceManager.count;
                var subjCount= subjectPage.subSubjectEntity.instanceManager.count;
                var organCount=organPage.subOrganEntity.instanceManager.count;
                var acCount= acTransPage.Account.subAccEntity.instanceManager.count;

                var subjList=[];
                var subjIDList=[];
                var organList=[];
                var organIDList=[];
                var acList=[];
                var acIDList=[];

                //read subject list
                for (var i=0;i<subjCount;i++){
                var curSubj=xfa.resolveNode("subjectPage.subSubjectEntity["+i+"]");
                var curSubjName="";

                if (!curSubj.subSubjectPartA.txtFamilyName.isNull && curSubj.subSubjectPartA.txtFamilyName.rawValue!=""){
                curSubjName += curSubj.subSubjectPartA.txtFamilyName.rawValue;
                }

                if (!curSubj.subSubjectPartA.txtGivenName.isNull &&　curSubj.subSubjectPartA.txtGivenName.rawValue!=""){
                if (curSubjName.length==0){
                curSubjName += curSubj.subSubjectPartA.txtGivenName.rawValue;
                }else{
                curSubjName += " "+ curSubj.subSubjectPartA.txtGivenName.rawValue;
                }
                }

                if (!curSubj.subSubjectPartA.txtMiddleName.isNull && curSubj.subSubjectPartA.txtMiddleName.rawValue!=""){
                if (curSubjName.length==0){
                curSubjName += curSubj.subSubjectPartA.txtMiddleName.rawValue;
                }else{
                curSubjName += " "+ curSubj.subSubjectPartA.txtMiddleName.rawValue;
                }
                }

                if (!curSubj.subSubjectPartA.txtChineseName.isNull && curSubj.subSubjectPartA.txtChineseName.rawValue!=""){
                if (curSubjName.length==0){
                curSubjName += curSubj.subSubjectPartA.txtChineseName.rawValue;
                }else{
                curSubjName += " "+ curSubj.subSubjectPartA.txtChineseName.rawValue;
                }
                }

                subjList.push(curSubjName);
                subjIDList.push(curSubj.subSubjectPartA.txtPersonID.rawValue);
                }

                //read organization list
                for (var i=0;i<organCount;i++){
                var curOrgan=xfa.resolveNode("organPage.subOrganEntity["+i+"]");
                var curOrganName="";

                if (!curOrgan.subOrganPartA.txtEngOrganName.isNull && curOrgan.subOrganPartA.txtEngOrganName.rawValue!=""){
                curOrganName+= curOrgan.subOrganPartA.txtEngOrganName.rawValue;
                }

                if (!curOrgan.subOrganPartA.txtChinOrganName.isNull && curOrgan.subOrganPartA.txtChinOrganName.rawValue!=""){
                if (curOrganName.length==0){
                curOrganName+= curOrgan.subOrganPartA.txtChinOrganName.rawValue;
                }else{
                curOrganName+= " "+ curOrgan.subOrganPartA.txtChinOrganName.rawValue;
                }
                }
                organList.push(curOrganName);
                organIDList.push(curOrgan.subOrganPartA.txtOrgID.rawValue);
                }
                //read account list
                for (var i=0;i<acCount;i++){
                var curAc=xfa.resolveNode("acTransPage.Account.subAccEntity["+i+"]");
                var curAcName="";

                if (!curAc.subAccPartA.txtAcNo.isNull && curAc.subAccPartA.txtAcNo.rawValue!=""){
                curAcName+= curAc.subAccPartA.txtAcNo.rawValue;
                }
                acList.push(curAcName);
                acIDList.push(curAc.subAccPartA.txtAccId.rawValue);
                }
                //set all tranactions' subject list and counterpart list
                for (var j=0;j<trxCount;j++){
                var curTrx= xfa.resolveNode("acTransPage.SuspiciousTransaction.subTransactionEntity["+j+"]");

                curTrx.subTransactionPartA.ddlSubject.clearItems();
                curTrx.subTransactionPartA.ddlCounterpart.clearItems();

                curTrx.subTransactionPartA.ddlSubject.addItem("---Subject---");
                curTrx.subTransactionPartA.ddlCounterpart.addItem("---Subject---");

                for (var i=0;i<subjList.length;i++){
                curTrx.subTransactionPartA.ddlSubject.addItem(subjList[i]);
                curTrx.subTransactionPartA.ddlCounterpart.addItem(subjList[i]);
                }
                curTrx.subTransactionPartA.ddlSubject.addItem("---Organization---");
                curTrx.subTransactionPartA.ddlCounterpart.addItem("---Organization---");

                for (var i=0;i<organList.length;i++){
                curTrx.subTransactionPartA.ddlSubject.addItem(organList[i]);
                curTrx.subTransactionPartA.ddlCounterpart.addItem(organList[i]);
                }
                curTrx.subTransactionPartA.ddlSubject.addItem("---Account---");
                curTrx.subTransactionPartA.ddlCounterpart.addItem("---Account---");

                for (var i=0;i<acList.length;i++){
                curTrx.subTransactionPartA.ddlSubject.addItem(acList[i]);
                curTrx.subTransactionPartA.ddlCounterpart.addItem(acList[i]);
                }
                //set hidden ID list
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.clearItems();
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.clearItems();

                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.addItem("---Subject---");
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.addItem("---Subject---");

                for (var i=0;i<subjIDList.length;i++){
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.addItem(subjIDList[i]);
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.addItem(subjIDList[i]);
                }

                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.addItem("---Organization---");
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.addItem("---Organization---");

                for (var i=0;i<organIDList.length;i++){
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.addItem(organIDList[i]);
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.addItem(organIDList[i]);
                }
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.addItem("---Account---");
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.addItem("---Account---");

                for (var i=0;i<acIDList.length;i++){
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.addItem(acIDList[i]);
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.addItem(acIDList[i]);
                }


                // set hidden field value back to hidden drop down list value and hidden subject list value
                if (!curTrx.subTransactionPartA.subHiddenList.txtSubjectPersonID.isNull){
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.rawValue=curTrx.subTransactionPartA.subHiddenList.txtSubjectPersonID.rawValue;
                }
                if (!curTrx.subTransactionPartA.subHiddenList.txtSubjectOrgID.isNull){
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.rawValue=curTrx.subTransactionPartA.subHiddenList.txtSubjectOrgID.rawValue;
                }
                if (!curTrx.subTransactionPartA.subHiddenList.txtSubjectAccID.isNull){
                curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.rawValue=curTrx.subTransactionPartA.subHiddenList.txtSubjectAccID.rawValue;
                }
                if (!curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.isNull){
                curTrx.subTransactionPartA.ddlSubject.rawValue=curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.rawValue;
                curTrx.subTransactionPartA.ddlSubject.selectedIndex=curTrx.subTransactionPartA.subHiddenList.ddlsubjectID.selectedIndex;
                }

                // set hidden field value back to hidden drop down list value and hidden counterpart list value
                if (!curTrx.subTransactionPartA.subHiddenList.txtCounterpartPersonID.isNull){
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.rawValue=curTrx.subTransactionPartA.subHiddenList.txtCounterpartPersonID.rawValue;
                }
                if (!curTrx.subTransactionPartA.subHiddenList.txtCounterpartOrgID.isNull){
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.rawValue=curTrx.subTransactionPartA.subHiddenList.txtCounterpartOrgID.rawValue;
                }
                if (!curTrx.subTransactionPartA.subHiddenList.txtCounterpartAccID.isNull){
                curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.rawValue=curTrx.subTransactionPartA.subHiddenList.txtCounterpartAccID.rawValue;
                }
                if (!curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.isNull){
                curTrx.subTransactionPartA.ddlCounterpart.rawValue=curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.rawValue;
                curTrx.subTransactionPartA.ddlCounterpart.selectedIndex=curTrx.subTransactionPartA.subHiddenList.ddlCounterpartID.selectedIndex;
                }

                //refresh transaction counterpart, ac no, others access control logic

                if (!curTrx.subTransactionPartA.ddlCounterpart.isNull){
                curTrx.subTransactionPartA.ddlCounterpart.access="open";
                curTrx.subTransactionPartA.txtCounterparAc.access="readOnly";
                curTrx.subTransactionPartA.txtCpOthers.access="readOnly";
                }
                if (!curTrx.subTransactionPartA.txtCounterparAc.isNull){
                curTrx.subTransactionPartA.ddlCounterpart.access="readOnly";
                curTrx.subTransactionPartA.txtCounterparAc.access="open";
                curTrx.subTransactionPartA.txtCpOthers.access="readOnly";
                }
                if (!curTrx.subTransactionPartA.txtCpOthers.isNull){
                curTrx.subTransactionPartA.ddlCounterpart.access="readOnly";
                curTrx.subTransactionPartA.txtCounterparAc.access="readOnly";
                curTrx.subTransactionPartA.txtCpOthers.access="open";
                }

                // refresh transaction +/- drop down list
                if (parseFloat(curTrx.subTransactionPartA.txtAmountHidden.rawValue)<0){
                curTrx.subTransactionPartA.ddlCreditOrDebit.rawValue="-";
                curTrx.subTransactionPartA.txtAmount.rawValue=parseFloat(curTrx.subTransactionPartA.txtAmountHidden.rawValue)*-1;
                }else{
                curTrx.subTransactionPartA.ddlCreditOrDebit.rawValue="+";
                curTrx.subTransactionPartA.txtAmount.rawValue=parseFloat(curTrx.subTransactionPartA.txtAmountHidden.rawValue);
                }
                }

                }
                function checkLastEntity(srcEntity,destPath){
                var noOfEntity=xfa.resolveNode(srcEntity).instanceManager.count;
                var lastEntity= xfa.resolveNode(srcEntity+"["+(Number(noOfEntity)-1)+"]");
                lastEntity.resolveNode(destPath).rawValue=1;

                }
                function cloneCCCToList(CCC,listAdd,list,listField){
                if (!CCC.isNull && CCC.rawValue !=""){
                var noOfRow= xfa.resolveNode(list).instanceManager.count;
                var lastRow= xfa.resolveNode(list+"["+ (noOfRow-1) +"]");

                if (!lastRow.resolveNode(listField).isNull&&lastRow.resolveNode(listField).rawValue!=""){
                xfa.resolveNode(listAdd).addInstance(1);
                }
                noOfRow= xfa.resolveNode(list).instanceManager.count;
                lastRow= xfa.resolveNode(list+"["+ (noOfRow-1) +"]");

                lastRow.resolveNode(listField).rawValue=CCC.rawValue;
                }
                }

                function cloneChkBoxToList(chkBox,listAdd,list,listField){
                if (chkBox.rawValue !="0"){
                var noOfRow= xfa.resolveNode(list).instanceManager.count;
                var lastRow= xfa.resolveNode(list+"["+ (noOfRow-1) +"]");

                if (!lastRow.resolveNode(listField).isNull){
                xfa.resolveNode(listAdd).addInstance(1);
                }

                noOfRow= xfa.resolveNode(list).instanceManager.count;
                lastRow= xfa.resolveNode(list+"["+ (noOfRow-1) +"]");

                //xfa.host.messageBox(noOfRow.toString());
                lastRow.resolveNode(listField).rawValue=chkBox.rawValue;
                }
                }
