                function genId(){
                var q=new Date();
                var year=q.getFullYear().toString();
                var month=(q.getMonth()+1).toString();
                if (month.length==1){
                month='0'+month;
                }
                var date=q.getDate().toString();
                if (date.length==1){
                date='0'+date;
                }
                var hour=q.getHours().toString();
                if (hour.length==1){
                hour='0'+hour;
                }
                var minute=q.getMinutes().toString();
                if (minute.length==1){
                minute='0'+minute;
                }
                var second=q.getSeconds().toString();
                if (second.length==1){
                second='0'+second;
                }
                var mSecond=q.getMilliseconds().toString();
                if (mSecond.length==1){
                mSecond='00'+mSecond;
                } else if (mSecond.length==2){
                mSecond='0'+mSecond;
                }
                return (year+month+date+hour+minute+second+mSecond);
                //xfa.host.messageBox(id);
                }
                function genDate(){
                var q=new Date();
                var year=q.getFullYear().toString();
                var month=(q.getMonth()+1).toString();
                if (month.length==1){
                month='0'+month;
                }
                var date=q.getDate().toString();
                if (date.length==1){
                date='0'+date;
                }
                return (year+"-"+month+"-"+date);
                //xfa.host.messageBox(id);
                }



                function refreshFileList(){
                //reset the whole list
                var messageArray=[];
                var message="";
                var totalSize=0;
                var containedSupportedChars=false;

                strSumAndReportBodyPage.subStrSummary.subAttachment.NoOfAttachments.rawValue=0;
                strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails.instanceManager.setInstances(1);
                strSumAndReportBodyPage.subStrSummary.subAttachment.subTotalFileSize.txtTotalFileSize.rawValue=0;

                xfa.resolveNode("strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails[0].subBtn.fileID").rawValue="";
                xfa.resolveNode("strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails[0].txtFileName").rawValue="";
                xfa.resolveNode("strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails[0].subFileSize.txtFileSize").rawValue="";

                var totalSize=strSumAndReportBodyPage.subStrSummary.subAttachment.subTotalFileSize.txtTotalFileSize.rawValue;
                var fileAttachments = event.target.dataObjects;

                //CASE-2020-231
                //unsupported filename
                var patt= /\`|\~|\!|\@|\#|\$|\%|\^|\*|\+|\=|\||\\|\'|\<|\,|\>|\?|\/|\"|\;|\:/g;
                var patt= /\!|\@|\#|\$|\%|\*|\+|\=|\||\<|\>|\?|\~|\`|\^|\:|\;|\'|\\|\/|\&/g;


                if (fileAttachments!=null){
                strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails.instanceManager.setInstances(fileAttachments.length);
                strSumAndReportBodyPage.subStrSummary.subAttachment.NoOfAttachments.rawValue=fileAttachments.length;

                fileAttachments.sort();
                for (var i=0;i<fileAttachments.length;i++){
                //Page1.attachmentsList.addItem(fileAttachments[i].path+"  ("+ fileAttachments[i].size+" bytes)");
                xfa.resolveNode("strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails["+i+"]").subBtn.fileID.rawValue= fileAttachments[i].name;
                xfa.resolveNode("strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails["+i+"]").txtFileName.rawValue= fileAttachments[i].path;
                xfa.resolveNode("strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails["+i+"]").subFileSize.txtFileSize.rawValue= ((fileAttachments[i].size/1024).toFixed(0));
                totalSize += xfa.resolveNode("strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails["+i+"]").subFileSize.txtFileSize.rawValue;

                //CASE-2020-231
                if (patt.test(fileAttachments[i].name)){
                containedSupportedChars=true;
                }
                }
                } else{
                strSumAndReportBodyPage.subStrSummary.subAttachment.fileList.fileDetails.instanceManager.setInstances(1);
                strSumAndReportBodyPage.subStrSummary.subAttachment.NoOfAttachments.rawValue=0;

                }
                //set the value for the field total file size
                strSumAndReportBodyPage.subStrSummary.subAttachment.subTotalFileSize.txtTotalFileSize.rawValue=totalSize;


                //save error message to array, total file size too large
                if ( totalSize > strSumAndReportBodyPage.subStrSummary.subAttachment.maxTotalFileSize.rawValue){
                messageArray.push("The total file size exceeded the maximum total file size allowed. Please delete some files.");
                }
                /*
                if (fileAttachments!=null && fileAttachments.length>strSumAndReportBodyPage.subStrSummary.subAttachment.maxNoOfAttachments.rawValue ){
                messageArray.push("The number of files uploaded exceeded the maximum number of files allowed. Please delete some files.");
                }
                */

                //CASE-2020-231
                if (containedSupportedChars==true){
                messageArray.push("The attachment list contains filename with unsupported characters. Please delete the files.");
                }


                if (messageArray.length>0){
                for (var i=0;i<messageArray.length;i++){
                if (messageArray.length==1){
                message= messageArray[i];
                } else{
                message+= '\r\n'+ messageArray[i];
                }
                }
                }

                if (message.length>0){
                xfa.host.messageBox(message.toString());
                }
                }

