                function moveToEntityPage(type){
                setAllPagesPresence('hidden');
                switch(type){
                case 'phoneEntity':
                showPhonePage();
                hideSignaturePage();
                break;

                case 'addressEntity':
                showAddressEntityPage();
                hideSignaturePage();
                break;

                case 'addressLine':
                showAddressLine();
                hideSignaturePage();
                break;

                case'addressFixed':
                showAddressFixed();
                hideSignaturePage();
                break;

                case 'editTransaction':
                showEditTransPage();
                hideSignaturePage();
                break;

                case 'subjectEntity':
                showSubjectPage();
                hideSignaturePage();
                break;

                case 'organEntity':
                showOrganPage();
                hideSignaturePage();
                break;
                }
                }
